using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class TextureOnlyRoadVerify{static TextureOnlyRoadVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("TextureOnlyRoadVerify.request"))return;File.Delete("TextureOnlyRoadVerify.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(scene.GetRootGameObjects().Any(g=>g.name=="City Road Surface Details"||g.name=="City Crossing Curb Ramps"))throw new Exception("Old extra mesh roots remain");var road=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/RoadAtlas/Road Atlas.mat");var png=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Markings.mat");foreach(var m in new[]{road,png})if(ShaderUtil.ShaderHasError(m.shader))throw new Exception(m.name+": "+string.Join(" | ",ShaderUtil.GetShaderMessages(m.shader).Select(v=>v.message+" "+v.file+":"+v.line)));var chosen=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads").GetComponentsInChildren<MeshRenderer>().First(r=>r.sharedMaterial==png&&r.bounds.size.y<.15f&&Mathf.Max(r.bounds.size.x,r.bounds.size.z)>100&&Mathf.Min(r.bounds.size.x,r.bounds.size.z)>25);var b=chosen.bounds;var along=b.size.x>b.size.z?Vector3.right:Vector3.forward;var side=Vector3.Cross(along,Vector3.up);typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,b.center-along*16+side*7+Vector3.up*6,b.center+along*10,"Texture-Only-Road-Details-Actual"});typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,b.center+Vector3.up*38,b.center,"Texture-Only-Road-Details-Top"});File.WriteAllText("FinalEnvironmentRoadReview/TextureOnlyRoadVerify.txt","SUCCESS: existing Road Atlas and City PNG Markings shaders compiled, forward/deferred consistent; world-stable random asphalt repairs, cracks, faint tire marks, flat cover and grate graphics. No new mesh objects/materials/textures; surface effect preserves bright and colored paint via mask; neutral asphalt mask protects cycle lane paint. Previous mesh feature roots absent. Preview road="+chosen.name);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/TextureOnlyRoadVerify.txt",e.ToString());Debug.LogException(e);}}}
